import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_previousSibling_TriageGen1Test {

    private Node parentNode;
    private Node testNode;
    private Node firstSibling;
    private Node secondSibling;
    private Node thirdSibling;

    @Before
    public void setUp() {
        Document doc = new Document("<div><p>First</p><p>Second</p><p>Third</p></div>");
        parentNode = doc.body();
        firstSibling = doc.select("p").get(0);
        secondSibling = doc.select("p").get(1);
        thirdSibling = doc.select("p").get(2);

        // Manually set parentNode for testNode
        testNode = secondSibling.clone();
        testNode.setParentNode(parentNode);
    }

    @Test
    public void testPreviousSibling_Exists() {
        Node result = testNode.previousSibling();
        assertNotNull(result);
        assertEquals(firstSibling, result);
    }












}

